from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import inch
import csv
path='/mnt/data/matrix_frame_report.pdf'; d=SimpleDocTemplate(path,pagesize=(612,792),rightMargin=55,leftMargin=55,topMargin=53,bottomMargin=48)
s=getSampleStyleSheet();s.add(ParagraphStyle(name='MyTitle',parent=s['Title'],fontSize=16,leading=20,spaceAfter=14));s.add(ParagraphStyle(name='Body2',parent=s['BodyText'],fontSize=10.3,leading=15,spaceAfter=11));s.add(ParagraphStyle(name='Sub2',parent=s['Heading2'],fontSize=12,spaceBefore=9,spaceAfter=7))
P=lambda t:Paragraph(t,s['Body2']);story=[Paragraph('Jacobian-Guided Moving Shears and Interval Wrapping in Nonlinear Oscillator Enclosures',s['MyTitle']),P('Flyxion | Research supplement | November 2026'),Paragraph('Model and controlled comparison',s['Sub2']),P('Consider the real two-oscillator Stuart–Landau reduction in collective and disagreement coordinates p=(u+v)/2 and m=(u-v)/2, with a fixed but unknown growth parameter a in [0.15,0.19], coupling k=0.7, and cumulative expenditure J. The equations are p’=ap−p³−3pm², m’=(a−2k)m−3p²m−m³, and J’=8 c_A k²m², with c_A=0.1. Initial intervals are p in [0.329,0.331], m in [0.119,0.121], J=0.'),P('The baseline propagates intervals in (p,m,J). The moving frame uses v=p−s m and propagates (v,m,J), with s initially zero and updated after each step using a rational midpoint-Jacobian heuristic. For each frozen s, v’=p’−s m’, with p=v+s m. Between steps, the change of frame is v_new=v_old+(s_old−s_new)m. Both methods use step size 0.01, 40-bit outward dyadic rounding, rational interval operations, and a Picard inclusion test. The same physical initial set is used.'),Paragraph('Numerical results',s['Sub2'])]
rows=list(csv.DictReader(open('/mnt/data/matrix_frame_results.csv')))
data=[['Horizon','Fixed state width','Moving state width','Fixed J upper','Moving J upper']]
for r in rows[1:]:data.append([f"{float(r['horizon']):.1f}",f"{float(r['fixed_width']):.6f}",f"{float(r['shear_width']):.6f}",f"{float(r['fixed_J_upper']):.7f}",f"{float(r['shear_J_upper']):.7f}"])
t=Table(data,colWidths=[65,112,112,102,102],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e6eaf0')),('GRID',(0,0),(-1,-1),.35,colors.grey),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(1,0),(-1,-1),'RIGHT'),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story.append(t)
story.extend([Spacer(1,12),Paragraph('Interpretation and limits',s['Sub2']),P('At H=0.8, the Jacobian-guided shear gives a 30.8% wider physical-coordinate enclosure than the fixed frame. This is not a failure of the underlying differential equations or the inclusion guarantee. It shows that a dynamically changing coordinate basis is not intrinsically wrapping-resistant: the interval hull introduced during each basis change can overwhelm any reduction in local linear coupling.'),P('The interval inclusion procedure is a conservative continuous-time enclosure for the reduced real system, provided the local Picard test succeeds. The calculation does not cover the full complex heterogeneous network, and the heuristic shear update is not an optimal Lohner or QR reconditioning algorithm. No general theorem that fixed frames dominate moving frames is asserted.'),Paragraph('Next proof obligation',s['Sub2']),P('A meaningful Lohner-type comparison should propagate a matrix of shared uncertainty generators and a separate nonlinear remainder, rather than immediately taking an interval hull after every frame transformation. It should also use an identical initial reachable set and identical rounding precision, and compare global reachable-set hulls and cumulative expenditure, not only per-cell widths.')]);d.build(story);print(path)
